async (page) => {
  const context = await page.context().browser().newContext({ viewport: { width: 1440, height: 900 } });
  const test = await context.newPage();
  const errors = [];
  test.on('pageerror', error => errors.push(error.message));
  const check = (condition, message) => { if (!condition) throw new Error(message); };
  try {
    await test.goto('http://127.0.0.1:8769');
    check(await test.locator('#view-title').innerText() === 'All sessions', 'All sessions is the default screen');
    check(await test.locator('[data-session]').count() === 7, 'Default screen includes assigned and unassigned sessions');
    check(await test.locator('#smart-links [data-view]').evaluateAll(nodes => nodes.map(n => n.dataset.view).join(',')) === 'all,favorites', 'Sidebar order');
    check(await test.locator('[data-collapse="unassigned"]').count() === 1, 'Unassigned group on the default screen');
    await test.locator('[data-view="all"]').click();
    check(await test.locator('[data-collapse]').last().getAttribute('data-collapse') === 'unassigned', 'Unassigned group is last');
    await test.locator('#grouping').selectOption('recent');
    check(await test.locator('[data-session]').evaluateAll(nodes => nodes.slice(-1).map(n => n.dataset.session).join(',')) === 'ses_demo_previous_rollout', 'Assigned sessions first in recent mode');
    await test.locator('#grouping').selectOption('project');
    await test.locator('[data-star="ses_demo_previous_rollout"]').click();
    await test.locator('[data-view="favorites"]').click();
    check(await test.locator('[data-session="ses_demo_previous_rollout"]').isVisible(), 'Unassigned favorite remains visible');
    await test.locator('[data-star="ses_demo_previous_rollout"]').click();
    await test.locator('[data-view="all"]').click();
    await test.locator('[data-open="ses_demo_search"]').click();
    await test.locator('#detail-move').click();
    await test.locator('#move-target').selectOption('');
    await test.getByRole('button', { name: 'Move sessions', exact: true }).click();
    await test.locator('[data-view="all"]').click();
    check(await test.locator('[data-collapse="unassigned"]').locator('..').locator('[data-session]').count() === 2, 'Unassign moves session into No project');
    await test.locator('#undo').click();
    check(await test.locator('[data-collapse="unassigned"]').locator('..').locator('[data-session]').count() === 1, 'Undo restores assignment');
    await test.locator('[data-view="all"]').click();
    check(await test.locator('[data-session]').count() === 7, 'All seven fixture sessions');
    const nav = await test.locator('nav > button').evaluateAll(nodes => nodes.map(n => n.getAttribute('aria-label')));
    check(nav[0] === 'Projects' && nav[1] === 'Kanban', 'Projects before Kanban');
    const atlas = test.locator('[data-collapse="atlas"]');
    await atlas.click();
    check(await atlas.getAttribute('aria-expanded') === 'false', 'Project collapsed indicator');
    check(!await test.locator('[data-session="ses_demo_search"]').isVisible(), 'Collapsed project hides sessions');
    await test.reload();
    check(await test.locator('#view-title').innerText() === 'All sessions', 'Reload opens All sessions');
    await test.locator('[data-view="all"]').click();
    check(await atlas.getAttribute('aria-expanded') === 'false', 'Collapse persistence');
    await atlas.focus();
    await test.keyboard.press('Enter');
    check(await test.locator('[data-session="ses_demo_search"]').isVisible(), 'Keyboard expands project');
    await test.locator('#toggle-all').click();
    check(await test.locator('[data-session]:visible').count() === 0, 'Collapse all');
    check(await test.locator('#toggle-all').getAttribute('aria-label') === 'Expand all projects', 'Expand all label');
    await test.locator('#toggle-all').click();
    check(await test.locator('[data-session]:visible').count() === 7, 'Expand all');
    await test.locator('#project-tree-toggle').click();
    check(!await test.locator('#project-links').isVisible(), 'Sidebar projects collapse');
    await test.locator('#project-tree-toggle').click();
    const searchRow = test.locator('[data-session="ses_demo_search"]');
    check(await searchRow.locator('.worked').innerText() === '10h 59m', 'Observed session runtime');
    check(await searchRow.locator('.context-usage').innerText() === '42%', 'Context percentage');
    check((await searchRow.locator('.context-usage').getAttribute('title')).includes('42,000 / 100,000'), 'Context token tooltip');
    check(await searchRow.locator('.top-model').innerText() === 'glm-5.3', 'Model by observed time');
    check(await test.locator('[data-session="ses_demo_previous_rollout"] .worked').innerText() === '—', 'Unknown duration remains unknown');
    check(await test.locator('[data-tag], #tag-dialog, #tag-selected').count() === 0, 'Tags removed');
    await test.locator('[data-view="aurora"]').click();
    const research = test.locator('[data-collapse="group:aurora:research"]');
    const work = test.locator('[data-collapse="group:aurora:work"]');
    const uncategorized = test.locator('[data-collapse="group:aurora:none"]');
    check(await research.locator('..').locator('[data-session]').count() === 2, 'Research has two sessions');
    check(await work.locator('..').locator('[data-session]').count() === 1, 'Work has one session');
    check(await uncategorized.locator('..').locator('[data-session]').count() === 1, 'One session is uncategorized');
    await research.click();
    check(!await test.locator('[data-session="ses_demo_review"]').isVisible(), 'Group collapses');
    await research.click();
    await test.locator('#new-group').click();
    await test.locator('#group-name').fill('research');
    await test.getByRole('button', { name: 'Create group', exact: true }).click();
    check(await test.locator('#group-name').evaluate(el => !el.validity.valid), 'Duplicate group rejected');
    await test.locator('#group-name').fill('Review');
    await test.getByRole('button', { name: 'Create group', exact: true }).click();
    const newGroup = test.locator('[data-group-drop]').filter({ hasText: 'Review' });
    check(await newGroup.count() === 1, 'Empty group created');
    await test.locator('[data-session="ses_demo_release"]').dragTo(newGroup);
    check(await newGroup.locator('..').locator('[data-session]').count() === 1, 'Drag to empty group');
    await test.locator('#undo').click();
    check(await uncategorized.locator('..').locator('[data-session]').count() === 1, 'Undo group move');
    await test.locator('[data-check="ses_demo_review"]').check();
    await test.locator('[data-check="codex:00000000-0000-4000-8000-000000000003"]').check();
    await test.locator('#move-selected').click();
    await test.locator('#move-group').selectOption('work');
    await test.getByRole('button', { name: 'Move sessions', exact: true }).click();
    check(await work.locator('..').locator('[data-session]').count() === 3, 'Bulk move to group');
    await test.locator('#undo').click();
    await test.locator('[data-open="ses_demo_review"]').click();
    await test.locator('#detail-move').click();
    await test.locator('#move-target').selectOption('atlas');
    check(await test.locator('#move-group').inputValue() === '', 'Project change resets group destination');
    await test.getByRole('button', { name: 'Move sessions', exact: true }).click();
    check(await test.evaluate(() => !state.sessionGroups.ses_demo_review), 'Cross-project move clears old group');
    await test.locator('#undo').click();
    check(await test.evaluate(() => state.sessionGroups.ses_demo_review === 'research'), 'Undo restores old group');
    await test.reload();
    await test.locator('[data-view="aurora"]').click();
    check(await newGroup.count() === 1, 'New group persists');
    await test.locator('[data-view="atlas"]').click();
    check(await test.locator('[data-group-drop]').filter({ hasText: 'Review' }).count() === 0, 'Groups are scoped to project');
    await test.locator('#reset').click();
    await test.locator('[data-view="all"]').click();
    await test.locator('[data-view="favorites"]').click();
    check(await test.locator('[data-session]').count() === 2, 'Initial favorites');
    await test.locator('[data-star]').first().click();
    check(await test.locator('[data-session]').count() === 1, 'Remove favorite');
    await test.locator('#reset').click();
    await test.locator('[data-view="all"]').click();
    await test.locator('[data-check="ses_demo_search"]').check();
    await test.locator('[data-check="ses_demo_previous_rollout"]').check();
    check(await test.locator('#selection-count').innerText() === '2 selected', 'Bulk selection');
    await test.locator('#move-selected').click();
    await test.locator('#move-target').selectOption('aurora');
    await test.getByRole('button', { name: 'Move sessions', exact: true }).click();
    check(await test.evaluate(() => state.assignments.ses_demo_search === 'aurora'), 'Bulk move');
    await test.locator('#undo').click();
    check(await test.evaluate(() => state.assignments.ses_demo_search === 'atlas'), 'Undo move');
    await test.locator('[data-session="ses_demo_search"]').dragTo(test.locator('[data-drop="aurora"]'));
    check(await test.evaluate(() => state.assignments.ses_demo_search === 'aurora'), 'Drag move');
    await test.locator('[data-open="ses_demo_search"]').click();
    check(await test.locator('#detail').innerText().then(t => t.includes('/Users/demo/Projects/atlas')), 'Original folder preserved');
    await test.locator('#close-detail').click();
    await test.getByRole('button', { name: 'New project', exact: true }).first().click();
    await test.locator('#project-name').fill('Release planning');
    await test.getByRole('button', { name: 'Create project', exact: true }).click();
    check(await test.locator('#view-title').innerText() === 'Release planning', 'Create project');
    check(await test.locator('.empty').isVisible(), 'Empty project');
    await test.reload();
    check(await test.locator('#view-title').innerText() === 'All sessions', 'Reload opens All sessions');
    await test.locator('[data-view="all"]').click();
    check(await test.locator('[data-drop]').count() === 3, 'Project persistence');
    check(await test.evaluate(() => state.assignments.ses_demo_search === 'aurora'), 'Move persistence');
    await test.locator('#search').fill('cache');
    check(await test.locator('[data-session]').count() === 1, 'Search');
    await test.locator('#agent-filter').selectOption('opencode');
    check(await test.locator('.empty').isVisible(), 'Combined filters empty state');
    await test.locator('#reset').click();
    await test.locator('[data-view="all"]').click();
    await test.locator('#kanban-tab').click();
    check(await test.locator('#kanban-view .column').count() === 3, 'Kanban columns');
    check(!await test.locator('.sidebar').isVisible(), 'No history sidebar on Kanban');
    await test.screenshot({ path: '/private/tmp/kliprun-projects-kanban.png' });
    await test.locator('#projects-tab').click();
    await test.locator('[data-view="all"]').click();
    await test.evaluate(() => { document.getElementById('toast').hidden = true; });
    for (const width of [1440, 980, 700, 600]) {
      await test.setViewportSize({ width, height: 900 });
      check(await test.evaluate(() => document.documentElement.scrollWidth <= innerWidth), `No page overflow at ${width}`);
      check(await test.locator('.session-list').first().evaluate(el => el.scrollWidth <= el.clientWidth), `No list overflow at ${width}`);
      check(await test.locator('.metrics').first().evaluate(el => el.getBoundingClientRect().right <= el.closest('.row-main').getBoundingClientRect().right + 1), `Metrics fit at ${width}`);
      await test.locator('[data-open="ses_demo_search"]').click();
      check(await test.locator('#detail').evaluate(el => el.getBoundingClientRect().right <= innerWidth), `Preview fits at ${width}`);
      await test.locator('#close-detail').click();
    }
    await test.screenshot({ path: '/private/tmp/kliprun-projects-small.png' });
    await test.setViewportSize({ width: 1440, height: 900 });
    await test.screenshot({ path: '/private/tmp/kliprun-projects-all.png' });
    await test.locator('[data-view="aurora"]').click();
    await test.screenshot({ path: '/private/tmp/kliprun-project-groups.png' });
    for (const width of [980, 700, 600]) {
      await test.setViewportSize({ width, height: 750 });
      check(await test.evaluate(() => document.documentElement.scrollWidth <= innerWidth), `Project groups fit at ${width}`);
    }
    await test.screenshot({ path: '/private/tmp/kliprun-project-groups-small.png' });
    check(errors.length === 0, `Browser errors: ${errors.join(', ')}`);
    return { passed: true, checks: 'Single All sessions default, assigned/unassigned ordering, unassigned favorites, assignment removal and undo, collapse/expand, keyboard, project groups, group creation, drag, bulk grouping, cross-project moves, group persistence, metrics and unknown values, navigation, favorites, selection, moves, undo, drag, original folder, project creation, persistence, filters, Kanban, preview, four viewport widths', errors };
  } finally { await context.close(); }
}
